async function readLease(root:StorageRoot){if(isPortableRoot(root))return null;try{const directory=await browserOperationalDirectory(root),handle=await directory.getFileHandle(leaseFile),file=await handle.getFile();if(file.size>16*1024)throw new Error('Session lease exceeds the size limit.');const value=JSON.parse(await file.text()) as Partial<SessionLease>;if(typeof value.sessionId==='string'&&value.sessionId.length<=100&&typeof value.actor==='string'&&value.actor.length<=500&&typeof value.updated==='string'&&value.updated.length<=50)return value as SessionLease}catch(error){if(!(error instanceof DOMException&&error.name==='NotFoundError'))void reportOperationalError('Session lease read failed.',error,trackerWindow().__activeSystemId,{audit:false})}return null}
