function warnAuditFailure(ok:boolean){if(!ok)alert(`The action completed, but the tamper-evident audit log could not be verified or extended. Stop making changes and check the mapped shared folder.${lastAuditError?`\n\nDetails: ${lastAuditError}`:''}`)}
async function writeErrorReport(context:string,detail:string,systemId?:string){const root=systemId?rootFor(systemId):undefined;if(!root)return'';const generatedAtUtc=new Date().toISOString(),day=generatedAtUtc.slice(0,10),filename=`error-report-${day}.txt`,reportId=`ERR-${generatedAtUtc.replace(/[-:.TZ]/g,'').slice(0,14)}-${crypto.randomUUID().slice(0,8).toUpperCase()}`,body=[`R.A.P.T.O.R. Error Entry`,`Application: Role-Based Access Personnel Tracking & Oversight Registry`,`Report ID: ${reportId}`,`Generation Time UTC: ${generatedAtUtc}`,`Windows Operator: ${currentActor()}`,`Application Version: ${applicationVersion}`,`Rule-Set Version: ${complianceRuleSetVersion}`,`Information System ID: ${systemId??'Unavailable'}`,`Context: ${oneLine(context)}`,'Details:',errorReportText(detail),'','Review this daily report in Notepad. Preserve it with inspection records if an error affected evidence processing.'].join('\r\n');if(isPortableRoot(root)){const response=await portableRequest(root,`error-report?filename=${encodeURIComponent(filename)}`,{method:'POST',headers:{'Content-Type':'text/plain; charset=utf-8'},body});const result=await response.json() as{saved?:string};return result.saved??`System/Error Reports/${filename}`}const directory=await browserSupportDirectory(root,'Error Reports'),file=await directory.getFileHandle(filename,{create:true}),existing=await file.getFile(),entry=`${existing.size?'\r\n':''}${body}\r\n`,entryBytes=new TextEncoder().encode(entry);if(existing.size+entryBytes.byteLength>100*1024*1024)throw new Error('The daily error report exceeds the 100 MB safety limit.');const writer=await file.createWritable({keepExistingData:true});try{await writer.write({type:'write',position:existing.size,data:entry});await writer.close()}catch(error){await writer.abort().catch(()=>undefined);throw error}return`System/Error Reports/${filename}`}
