 const auditPromise=options?.audit!==false&&systemId&&root?bounded(()=>appendAudit(errorAuditAction(context,detail),systemId),'The audit error entry could not be written within 10 seconds.').catch(error=>{lastAuditError=errorDetail(error,'The audit error entry timed out.');return false}):Promise.resolve(false);
