 <section className={`storage-health ${health.status}`}><div className="health-summary"><span className="health-dot"/><div><strong>{health.status==='healthy'?'Storage Healthy':health.status==='saving'?'Saving…':health.status==='checking'?'Checking Storage…':health.status==='error'?'Storage Needs Attention':'Folder Not Mapped'}</strong><small>{health.message??(health.status==='unmapped'?'Map this system folder to enable protected storage.':'Database, Checksum, and Backup Status')}</small></div></div><div className="health-times"><span>Last Saved<b>{health.lastSaved?new Date(health.lastSaved).toLocaleString():'—'}</b></span><span>Last Backup<b>{health.lastBackup?new Date(health.lastBackup).toLocaleString():'—'}</b></span><span>Last Sync<b>{health.lastSync?new Date(health.lastSync).toLocaleString():'—'}</b></span></div>{canWrite&&<button disabled={!rootFor(effectiveSelected)||health.status==='saving'||health.status==='checking'} onClick={()=>void verifyStorage()}>Verify Storage</button>}</section>
