 const eligibleArchiveIds=pending.archiveCandidates.filter(candidate=>!candidate.requiresCandidateId||approved.includes(candidate.requiresCandidateId)).map(candidate=>candidate.id),allArchivesSelected=eligibleArchiveIds.length>0&&eligibleArchiveIds.every(id=>archiveSelected.includes(id)),optionalZipIds=pending.zipCandidates.filter(candidate=>!automaticZipSet.has(candidate.id)).map(candidate=>candidate.id),allZipsSelected=optionalZipIds.length>0&&optionalZipIds.every(id=>zipSelected.includes(id)),allReworkSelected=pending.reworkCandidates.length>0&&pending.reworkCandidates.every(candidate=>reworkSelected.includes(candidate.id));
 const newUserSaarCorrections=pending.reworkCandidates.filter(candidate=>filenameMatchesKind(candidate.filename,'SAAR')),timedOutFiles=pending.rejected.filter(syncRejectionTimedOut),rejectedFiles=pending.rejected.filter(item=>!syncRejectionTimedOut(item)),collisionPage=paginateItems(pending.collisionCandidates,cleanupPage),reworkPage=paginateItems(pending.reworkCandidates,cleanupPage),archivePage=paginateItems(pending.archiveCandidates,cleanupPage),zipPage=paginateItems(pending.zipCandidates,cleanupPage),externalIssuePage=paginateItems(pending.externalSharedAdditions,issuePage),identityIssuePage=paginateItems(pending.identityConflicts,issuePage),contentIssuePage=paginateItems(pending.contentDuplicates,issuePage),saarIssuePage=paginateItems(newUserSaarCorrections,issuePage),unmatchedIssuePage=paginateItems(pending.unmatched,issuePage),bypassedIssuePage=paginateItems(timedOutFiles,issuePage),rejectedIssuePage=paginateItems(rejectedFiles,issuePage),reworkPageIds=reworkPage.items.map(candidate=>candidate.id),archivePageIds=archivePage.items.filter(candidate=>!candidate.requiresCandidateId||approved.includes(candidate.requiresCandidateId)).map(candidate=>candidate.id),zipPageIds=zipPage.items.filter(candidate=>!automaticZipSet.has(candidate.id)).map(candidate=>candidate.id),allReworkPageSelected=reworkPageIds.length>0&&reworkPageIds.every(id=>reworkSelected.includes(id)),allArchivePageSelected=archivePageIds.length>0&&archivePageIds.every(id=>archiveSelected.includes(id)),allZipPageSelected=zipPageIds.length>0&&zipPageIds.every(id=>zipSelected.includes(id));
