 function toggleAllZips(){setZipSelected(current=>allZipsSelected?current.filter(id=>!optionalZipIds.includes(id)):[...new Set([...current,...optionalZipIds])])}
 function togglePageZips(){setZipSelected(current=>allZipPageSelected?current.filter(id=>!zipPageIds.includes(id)):[...new Set([...current,...zipPageIds])])}
 function toggleRework(id:string,checked:boolean){setReworkSelected(current=>checked?[...new Set([...current,id])]:current.filter(value=>value!==id))}
 function toggleAllRework(){const ids=pending.reworkCandidates.map(candidate=>candidate.id);setReworkSelected(allReworkSelected?[]:ids)}
 function togglePageRework(){setReworkSelected(current=>allReworkPageSelected?current.filter(id=>!reworkPageIds.includes(id)):[...new Set([...current,...reworkPageIds])])}
